1	// Fault-injection shims for the regression-test build of envelopefile.
2	//
3	// This file is linked together with src/main.cpp into the separate
4	// `envelopefile_testable` binary using the linker's --wrap option, so every
5	// open/write/fsync/close call made by the product code is routed through the
6	// __wrap_* functions below. The production binary is completely unaffected.
7	//
8	// Injection is controlled entirely through environment variables so the test
9	// driver can select a scenario per process run:
10	//
11	//   EF_TEST_TARGET          Only inject faults for this exact path. When
12	//                           unset, any file created with O_CREAT|O_EXCL is
13	//                           considered the key file under test.
14	//   EF_TEST_FAIL_WRITE=1    write() on the key file fails with EIO.
15	//   EF_TEST_PARTIAL_WRITE=N write() on the key file returns at most N bytes
16	//                           per call (the caller must loop to complete).
17	//   EF_TEST_FAIL_FSYNC=1    fsync() on the key file fails with EIO.
18	//   EF_TEST_FAIL_CLOSE=1    close() on the key file reports EIO (the
19	//                           descriptor is still really closed, matching the
20	//                           POSIX guarantee that close() releases the fd).
21	//   EF_TEST_FAIL_FCHMOD=1   fchmod() on the key file fails with EPERM, so the
22	//                           0600 permission guarantee cannot be established.
23	//   EF_TEST_FAIL_FSTAT=1    fstat() on the key file fails with EIO even though
24	//                           fchmod() reported success: the post-set permission
25	//                           verification cannot read the file's metadata.
26	//   EF_TEST_FSTAT_MODE=mmm  fstat() succeeds but the permission bits reported
27	//                           back are replaced with the octal mode mmm (only the
28	//                           low 12 bits are taken; file type bits are kept),
29	//                           simulating a filesystem where fchmod() reports
30	//                           success but the effective mode differs, e.g. 0644
31	//                           (group/other can still read) or 0400 (owner write
32	//                           was stripped).
33	//
34	// For deterministic coverage of the write loop itself, a per-call script can
35	// be supplied:
36	//
37	//   EF_TEST_WRITE_SCRIPT=t1,t2,...
38	//                           Each token describes the outcome of one write()
39	//                           call on the key file, consumed in order; once the
40	//                           list is exhausted every further call succeeds
41	//                           normally. Tokens:
42	//                             ok    - write the whole requested buffer
43	//                             N     - short write: at most N (decimal) bytes
44	//                             intr  - fail with EINTR, no bytes written
45	//                             eio   - fail irrecoverably with EIO
46	//                             zero  - return 0 with bytes still pending
47	//
48	//   EF_TEST_WRITE_LOG=path  Record what the write loop actually did, so the
49	//                           test driver can prove byte continuity across
50	//                           retries. On the first key-file write the original
51	//                           32-byte key is snapshotted; every subsequent call
52	//                           is checked to advance from the current offset with
53	//                           a buffer that is a slice of that same snapshot
54	//                           (i.e. the key is neither regenerated, duplicated,
55	//                           nor dropped). Every call is also checked to pass a
56	//                           pointer INTO the exact buffer RAND_bytes filled
57	//                           (at the current offset), so the bytes that reach
58	//                           the file are provably the ones the later
59	//                           OPENSSL_cleanse wipes — not a copy living
60	//                           elsewhere. The file receives one line:
61	//                             VERIFY <64 lowercase hex digits>
62	//                           followed by one line per write() call:
63	//                             CALL <offset> <requested> <returned> [<errno>]
64	//                           (the errno field is only present when returned is
65	//                           -1). A continuity violation is recorded as a
66	//                             VERIFY-FAILED <reason>
67	//                           line and aborts the process, since it means the
68	//                           product code violated its own write contract.
69	//
70	// The secure random source can be made to fail deterministically:
71	//
72	//   EF_TEST_FAIL_RAND=1       RAND_bytes reports failure (returns 0).
73	//   EF_TEST_RAND_PARTIAL=N    before failing, N marker bytes (0xA5) are
74	//                             written into the caller's key buffer,
75	//                             simulating a CSPRNG that dies mid-fill. The
76	//                             marker lets the test driver prove the partial
77	//                             data is neither saved nor leaked.
78	//   EF_TEST_RAND_ERROR_DETAIL=1
79	//                             leave a descriptive OpenSSL error on the
80	//                             thread's error queue so the failure carries
81	//                             detail text; when unset the queue is cleared
82	//                             instead, exercising the no-detail message.
83	//
84	// Key-buffer lifecycle events are recorded when requested:
85	//
86	//   EF_TEST_KEY_LOG=path      one line per event:
87	//                               RAND <requested> partial=<N> result=<ok|fail>
88	//                               CLEANSED-KEY <len>
89	//                               CLEANSE-STATE writes=<N> keyfd=<open|closed>
90	//                             The CLEANSED-KEY line is emitted when the
91	//                             buffer previously handed to RAND_bytes is
92	//                             wiped via OPENSSL_cleanse, proving the key
93	//                             (including any partial bytes) does not survive
94	//                             the operation in memory. It is followed by a
95	//                             CLEANSE-STATE line capturing how many key bytes
96	//                             had been written and whether the key-file
97	//                             descriptor was already closed at that moment,
98	//                             so the test driver can prove the wipe happened
99	//                             only after the save was complete (never before,
100	//                             which would save wiped data).
101	//
102	// Only the file descriptor opened for the key file is instrumented; all
103	// other I/O (stdout, stderr, OpenSSL internals, the log file itself) passes
104	// through untouched.
105	
106	#include <openssl/err.h>
107	#include <openssl/opensslv.h>
108	#include <openssl/rand.h>
109	
110	#include <cerrno>
111	#include <cstdarg>
112	#include <cstdint>
113	#include <cstdio>
114	#include <cstdlib>
115	#include <cstring>
116	#include <fcntl.h>
117	#include <sys/stat.h>
118	#include <unistd.h>
119	
120	extern "C" {
121	
122	// Real libc/libcrypto entry points provided by the --wrap linker mechanism.
123	int __real_open(const char* path, int flags, ...);
124	int __real_fchmod(int fd, mode_t mode);
125	int __real_fstat(int fd, struct stat* info);
126	ssize_t __real_write(int fd, const void* buffer, size_t count);
127	int __real_fsync(int fd);
128	int __real_close(int fd);
129	int __real_RAND_bytes(unsigned char* buf, int num);
130	void __real_OPENSSL_cleanse(void* ptr, size_t len);
131	
132	namespace {
133	
134	constexpr std::size_t kKeyBytes = 32;
135	
136	// Descriptor currently known to belong to the key file under test, or -1.
137	int g_keyFd = -1;
138	
139	// Key buffer most recently handed to RAND_bytes, so the OPENSSL_cleanse
140	// wrapper can recognise (and log) its wipe.
141	unsigned char* g_randBuf = nullptr;
142	int g_randBufSize = 0;
143	
144	// Continuity bookkeeping for EF_TEST_WRITE_LOG.
145	unsigned char g_keySnapshot[kKeyBytes];
146	bool g_haveSnapshot = false;     // the snapshot below is valid
147	std::size_t g_progress = 0;      // bytes acknowledged so far (pre-call offset)
148	
149	bool envFlagSet(const char* name) {
150	    const char* value = std::getenv(name);
151	    return value != nullptr && value[0] != '\0' && std::strcmp(value, "0") != 0;
152	}
153	
154	bool isKeyPath(const char* path) {
155	    const char* target = std::getenv("EF_TEST_TARGET");
156	    return target == nullptr || std::strcmp(path, target) == 0;
157	}
158	
159	bool isKeyFd(int fd) {
160	    return fd != -1 && fd == g_keyFd;
161	}
162	
163	// Preserve errno across the bookkeeping I/O so the injected failure code is
164	// what the product code actually observes.
165	class ErrnoSaver {
166	public:
167	    ErrnoSaver() : saved_(errno) {}
168	    ~ErrnoSaver() { errno = saved_; }
169	
170	private:
171	    int saved_;
172	};
173	
174	void logLine(const char* pathEnv, const char* mode, const char* text) {
175	    const char* logPath = std::getenv(pathEnv);
176	    if (logPath == nullptr || logPath[0] == '\0') {
177	        return;
178	    }
179	    ErrnoSaver saver;
180	    std::FILE* file = std::fopen(logPath, mode);
181	    if (file == nullptr) {
182	        return;
183	    }
184	    std::fputs(text, file);
185	    std::fputc('\n', file);
186	    std::fclose(file);
187	}
188	
189	void logKeyLine(const char* text) {
190	    logLine("EF_TEST_KEY_LOG", "a", text);
191	}
192	
193	void logVerifyHeader(const unsigned char* buffer) {
194	    constexpr std::size_t kPrefix = 7;  // strlen("VERIFY ")
195	    char line[kPrefix + 2 * kKeyBytes + 1];
196	    char* out = line;
197	    std::strcpy(out, "VERIFY ");
198	    out += 7;
199	    static const char hex[] = "0123456789abcdef";
200	    for (std::size_t i = 0; i < kKeyBytes; ++i) {
201	        *out++ = hex[buffer[i] >> 4];
202	        *out++ = hex[buffer[i] & 0x0f];
203	    }
204	    *out = '\0';
205	    logLine("EF_TEST_WRITE_LOG", "w", line);
206	}
207	
208	void logCall(std::size_t offset, std::size_t requested,
209	             ssize_t returned, int reportedErrno) {
210	    char line[128];
211	    if (returned < 0) {
212	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd %d",
213	                      offset, requested, returned, reportedErrno);
214	    } else {
215	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd",
216	                      offset, requested, returned);
217	    }
218	    logLine("EF_TEST_WRITE_LOG", "a", line);
219	}
220	
221	void logVerifyFailed(const char* reason) {
222	    char line[160];
223	    std::snprintf(line, sizeof(line), "VERIFY-FAILED %s", reason);
224	    logLine("EF_TEST_WRITE_LOG", "a", line);
225	}
226	
227	// On the first key-file write, snapshot the key; afterwards confirm that the
228	// caller resumes exactly at the acknowledged offset and presents the matching
229	// slice of the same key. Every call must also pass a pointer into the very
230	// buffer RAND_bytes filled (at the current offset): the bytes reaching the
231	// file are then provably the ones OPENSSL_cleanse later wipes, not an
232	// unwiped copy. Any mismatch is a product-code defect: abort so the
233	// regression run can never pass on a silently regenerated/garbled key.
234	void verifyIncomingBuffer(const void* buffer, std::size_t count) {
235	    if (std::getenv("EF_TEST_WRITE_LOG") == nullptr) {
236	        return;
237	    }
238	    const auto* bytes = static_cast<const unsigned char*>(buffer);
239	    if (g_randBuf != nullptr && bytes != g_randBuf + g_progress) {
240	        logVerifyFailed("write buffer is not the buffer filled by RAND_bytes");
241	        std::abort();
242	    }
243	    if (!g_haveSnapshot) {
244	        if (count != kKeyBytes) {
245	            logVerifyFailed("first write did not carry the whole 32-byte key");
246	            std::abort();
247	        }
248	        std::memcpy(g_keySnapshot, bytes, kKeyBytes);
249	        g_haveSnapshot = true;
250	        logVerifyHeader(g_keySnapshot);
251	        return;
252	    }
253	    if (g_progress > kKeyBytes) {
254	        logVerifyFailed("offset past end of key");
255	        std::abort();
256	    }
257	    const std::size_t remaining = kKeyBytes - g_progress;
258	    if (count != remaining) {
259	        logVerifyFailed("write length does not match the bytes still pending");
260	        std::abort();
261	    }
262	    if (std::memcmp(g_keySnapshot + g_progress, bytes, remaining) != 0) {
263	        logVerifyFailed("buffer is not the same key (key was regenerated?)");
264	        std::abort();
265	    }
266	}
267	
268	void resetWriteBookkeeping() {
269	    g_haveSnapshot = false;
270	    g_progress = 0;
271	}
272	
273	// Outcome of one scripted write() call.
274	enum class WriteOutcome {
275	    kPass,       // behave as the real syscall with the given count
276	    kShort,      // behave as the real syscall but cap the count
277	    kEintr,      // report a recoverable interrupt, nothing written
278	    kEio,        // report an irrecoverable I/O error
279	    kZero,       // report zero bytes with data still pending
280	};
281	
282	struct ScriptedCall {
283	    WriteOutcome outcome;
284	    long limit;  // valid for kShort
285	};
286	
287	// Parse the next EF_TEST_WRITE_SCRIPT token. Returns false once the script is
288	// exhausted (the caller should then behave normally).
289	bool nextScriptedCall(ScriptedCall& call) {
290	    static char script[512];
291	    static bool initialized = false;
292	    static char* saveptr = nullptr;
293	
294	    if (!initialized) {
295	        const char* raw = std::getenv("EF_TEST_WRITE_SCRIPT");
296	        if (raw == nullptr) {
297	            script[0] = '\0';
298	        } else {
299	            std::strncpy(script, raw, sizeof(script) - 1);
300	            script[sizeof(script) - 1] = '\0';
301	        }
302	        saveptr = script;
303	        initialized = true;
304	    }
305	
306	    char* token = ::strtok_r(nullptr, ",", &saveptr);
307	    if (token == nullptr) {
308	        return false;
309	    }
310	    if (std::strcmp(token, "ok") == 0) {
311	        call.outcome = WriteOutcome::kPass;
312	    } else if (std::strcmp(token, "intr") == 0) {
313	        call.outcome = WriteOutcome::kEintr;
314	    } else if (std::strcmp(token, "eio") == 0) {
315	        call.outcome = WriteOutcome::kEio;
316	    } else if (std::strcmp(token, "zero") == 0) {
317	        call.outcome = WriteOutcome::kZero;
318	    } else {
319	        char* end = nullptr;
320	        long limit = std::strtol(token, &end, 10);
321	        if (end != token && *end == '\0' && limit > 0) {
322	            call.outcome = WriteOutcome::kShort;
323	            call.limit = limit;
324	        } else {
325	            // An unknown token is a test-script bug: fail loudly rather than
326	            // silently behave as a normal write.
327	            std::fprintf(stderr,
328	                         "envelopefile_testable: invalid write script token "
329	                         "'%s'\n", token);
330	            call.outcome = WriteOutcome::kEio;
331	        }
332	    }
333	    return true;
334	}
335	
336	}  // namespace
337	
338	int __wrap_open(const char* path, int flags, ...) {
339	    mode_t mode = 0;
340	    if ((flags & O_CREAT) != 0) {
341	        va_list args;
342	        va_start(args, flags);
343	        mode = static_cast<mode_t>(va_arg(args, int));
344	        va_end(args);
345	    }
346	    int fd = __real_open(path, flags, mode);
347	    if (fd != -1 && (flags & O_CREAT) != 0 && (flags & O_EXCL) != 0 &&
348	        isKeyPath(path)) {
349	        g_keyFd = fd;
350	        resetWriteBookkeeping();
351	    }
352	    return fd;
353	}
354	
355	int __wrap_fchmod(int fd, mode_t mode) {
356	    if (isKeyFd(fd) && envFlagSet("EF_TEST_FAIL_FCHMOD")) {
357	        errno = EPERM;
358	        return -1;
359	    }
360	    return __real_fchmod(fd, mode);
361	}
362	
363	int __wrap_fstat(int fd, struct stat* info) {
364	    if (!isKeyFd(fd)) {
365	        return __real_fstat(fd, info);
366	    }
367	    // This is the post-fchmod verification read: fchmod itself already
368	    // reported success for the key fd when the code reaches fstat.
369	    if (envFlagSet("EF_TEST_FAIL_FSTAT")) {
370	        errno = EIO;
371	        return -1;
372	    }
373	    const int result = __real_fstat(fd, info);
374	    if (result == 0) {
375	        const char* forced = std::getenv("EF_TEST_FSTAT_MODE");
376	        if (forced != nullptr && forced[0] != '\0') {
377	            char* end = nullptr;
378	            const unsigned long forcedMode = std::strtoul(forced, &end, 8);
379	            if (end != forced && *end == '\0') {
380	                // Keep the file-type bits; replace only the permission bits
381	                // the product code verifies against exactly 0600.
382	                info->st_mode =
383	                    (info->st_mode & static_cast<mode_t>(~07777)) |
384	                    (static_cast<mode_t>(forcedMode) & 07777);
385	            }
386	        }
387	    }
388	    return result;
389	}
390	
391	ssize_t __wrap_write(int fd, const void* buffer, size_t count) {
392	    if (!isKeyFd(fd)) {
393	        return __real_write(fd, buffer, count);
394	    }
395	
396	    verifyIncomingBuffer(buffer, count);
397	
398	    const size_t requested = count;  // caller's original length for the log
399	    ScriptedCall call;
400	    const bool scripted = nextScriptedCall(call);
401	    if (scripted) {
402	        switch (call.outcome) {
403	            case WriteOutcome::kEintr:
404	                logCall(g_progress, requested, -1, EINTR);
405	                errno = EINTR;
406	                return -1;
407	            case WriteOutcome::kEio:
408	                logCall(g_progress, requested, -1, EIO);
409	                errno = EIO;
410	                return -1;
411	            case WriteOutcome::kZero:
412	                logCall(g_progress, requested, 0, 0);
413	                errno = 0;
414	                return 0;
415	            case WriteOutcome::kShort:
416	                if (count > static_cast<size_t>(call.limit)) {
417	                    count = static_cast<size_t>(call.limit);
418	                }
419	                break;
420	            case WriteOutcome::kPass:
421	                break;
422	        }
423	    } else {
424	        // Legacy single-knob injection, kept for the existing regressions.
425	        if (envFlagSet("EF_TEST_FAIL_WRITE")) {
426	            logCall(g_progress, requested, -1, EIO);
427	            errno = EIO;
428	            return -1;
429	        }
430	        const char* chunk = std::getenv("EF_TEST_PARTIAL_WRITE");
431	        if (chunk != nullptr) {
432	            const long limit = std::atol(chunk);
433	            if (limit > 0 && count > static_cast<size_t>(limit)) {
434	                count = static_cast<size_t>(limit);
435	            }
436	        }
437	    }
438	
439	    ssize_t result = __real_write(fd, buffer, count);
440	    logCall(g_progress, requested, result, errno);
441	    if (result > 0) {
442	        g_progress += static_cast<std::size_t>(result);
443	    }
444	    return result;
445	}
446	
447	int __wrap_fsync(int fd) {
448	    if (isKeyFd(fd) && envFlagSet("EF_TEST_FAIL_FSYNC")) {
449	        errno = EIO;
450	        return -1;
451	    }
452	    return __real_fsync(fd);
453	}
454	
455	int __wrap_close(int fd) {
456	    const bool wasKeyFd = isKeyFd(fd);
457	    const int result = __real_close(fd);
458	    if (wasKeyFd) {
459	        g_keyFd = -1;
460	        if (envFlagSet("EF_TEST_FAIL_CLOSE")) {
461	            // The descriptor is already closed for real; only the reported
462	            // status is faked, mirroring a genuine close(2) failure.
463	            errno = EIO;
464	            return -1;
465	        }
466	    }
467	    return result;
468	}
469	
470	int __wrap_RAND_bytes(unsigned char* buf, int num) {
471	    if (!envFlagSet("EF_TEST_FAIL_RAND")) {
472	        const int result = __real_RAND_bytes(buf, num);
473	        if (result == 1) {
474	            g_randBuf = buf;
475	            g_randBufSize = num;
476	            char line[96];
477	            std::snprintf(line, sizeof(line),
478	                          "RAND %d partial=0 result=ok", num);
479	            logKeyLine(line);
480	        }
481	        return result;
482	    }
483	
484	    g_randBuf = buf;
485	    g_randBufSize = num;
486	
487	    // Simulate a CSPRNG that wrote some bytes before dying: the caller must
488	    // not mistake the partial fill for a valid key.
489	    long partial = 0;
490	    const char* raw = std::getenv("EF_TEST_RAND_PARTIAL");
491	    if (raw != nullptr) {
492	        partial = std::atol(raw);
493	        if (partial < 0) {
494	            partial = 0;
495	        }
496	        if (partial > num) {
497	            partial = num;
498	        }
499	    }
500	    for (long i = 0; i < partial; ++i) {
501	        buf[i] = 0xA5;
502	    }
503	
504	    // Start from an empty error queue, then optionally leave a descriptive
505	    // OpenSSL error so the "detail" and "no detail" messages are both
506	    // exercised deterministically.
507	    ERR_clear_error();
508	    if (envFlagSet("EF_TEST_RAND_ERROR_DETAIL")) {
509	#if OPENSSL_VERSION_NUMBER >= 0x30000000L
510	        ERR_raise(ERR_LIB_RAND, 0x7f);
511	#else
512	        ERR_put_error(ERR_LIB_RAND, 0, 0x7f, __FILE__, __LINE__);
513	#endif
514	    }
515	
516	    char line[96];
517	    std::snprintf(line, sizeof(line), "RAND %d partial=%ld result=fail",
518	                  num, partial);
519	    logKeyLine(line);
520	    return 0;
521	}
522	
523	void __wrap_OPENSSL_cleanse(void* ptr, size_t len) {
524	    if (ptr != nullptr && ptr == g_randBuf) {
525	        char line[96];
526	        std::snprintf(line, sizeof(line), "CLEANSED-KEY %zu", len);
527	        logKeyLine(line);
528	        // Record how far the save had progressed when the wipe happened, so
529	        // the test driver can prove a successful save was not preceded by
530	        // the wipe (which would have saved wiped data).
531	        char state[96];
532	        std::snprintf(state, sizeof(state),
533	                      "CLEANSE-STATE writes=%zu keyfd=%s",
534	                      g_progress, g_keyFd == -1 ? "closed" : "open");
535	        logKeyLine(state);
536	        // The buffer is about to be released; do not match a stale address.
537	        g_randBuf = nullptr;
538	        g_randBufSize = 0;
539	    }
540	    __real_OPENSSL_cleanse(ptr, len);
541	}
542	
543	}  // extern "C"
544

