13	#include <sys/types.h>
14	#include <unistd.h>
15	
16	namespace {
17	
18	constexpr std::size_t kKeyBytes = 32;
19	
20	constexpr const char* kVersionString = "envelopefile 0.1.0\n";
21	constexpr const char* kUsage =
22	    "Usage:\n"
23	    "  envelopefile --version\n"
24	    "  envelopefile keygen --output <path>\n";
25	constexpr const char* kKeygenUsage =
26	    "Usage: envelopefile keygen --output <path>\n";
27	
28	// Owns raw key material and wipes it with OPENSSL_cleanse on every exit path.
29	class SecureBuffer {
30	public:
31	    SecureBuffer() = default;
32	    explicit SecureBuffer(std::size_t size) : size_(size) {
33	        data_ = new unsigned char[size_];
34	    }
35	    ~SecureBuffer() { wipe(); }
36	
37	    SecureBuffer(const SecureBuffer&) = delete;
38	    SecureBuffer& operator=(const SecureBuffer&) = delete;
39	    SecureBuffer(SecureBuffer&& other) noexcept
40	        : data_(other.data_), size_(other.size_) {
41	        other.data_ = nullptr;
42	        other.size_ = 0;
43	    }
44	    SecureBuffer& operator=(SecureBuffer&&) = delete;
45	
46	    unsigned char* data() { return data_; }
47	    std::size_t size() const { return size_; }
48	
49	    void wipe() {
50	        if (data_ != nullptr) {
51	            OPENSSL_cleanse(data_, size_);
52	            delete[] data_;
53	            data_ = nullptr;
54	            size_ = 0;
55	        }
56	    }
57	
58	private:
59	    unsigned char* data_ = nullptr;
60	    std::size_t size_ = 0;
61	};
62	
63	std::string opensslErrorString() {
64	    unsigned long code = ERR_peek_last_error();
65	    if (code == 0) {
66	        return {};
67	    }
68	    char buffer[256];
69	    ERR_error_string_n(code, buffer, sizeof(buffer));
70	    return buffer;
71	}
72	
73	// Fills the buffer using OpenSSL's CSPRNG (backed by the operating system's
74	// secure random source). Never seeded from time, paths, or ordinary PRNGs.
75	bool generateKey(SecureBuffer& key, std::string& error) {
76	    if (RAND_bytes(key.data(), static_cast<int>(key.size())) != 1) {
77	        error = "secure random source failed";
78	        const std::string detail = opensslErrorString();
79	        if (!detail.empty()) {
80	            error += ": ";
81	            error += detail;
82	        }
83	        return false;
84	    }
85	    return true;
86	}
87	
88	std::string errnoDescription(int errorNumber) {
89	    const char* description = std::strerror(errorNumber);
90	    return description != nullptr ? description : "unknown error";
91	}
92	
93	// Why a save attempt ended the way it did. kSaved is the only success; every
94	// other status is reported to the user with an explanatory message.
95	enum class KeySaveStatus {
96	    kSaved,          // all key bytes written, fsynced, and closed; mode 0600
97	    kNotCreated,     // open() produced no file, so nothing had to be cleaned
98	    kCleanedUp,      // this run created the file, failed, and removed it
99	    kCleanupFailed,  // this run created the file, failed, and removal failed
100	};
101	
102	// Complete outcome of one keygen save attempt: whether it succeeded, why it
103	// failed when it did, and whether the file this run created was cleaned up.
104	// The save logic itself writes nothing to stdout or stderr; the command line
105	// reports error, and additionally reports removalWarning only when cleanup
106	// failed, so a failed removal can never mask the original save failure and a
107	// caller can tell "removed" apart from "could not remove" instead of inferring
108	// deletion from failure alone. Neither string ever contains key material.
109	struct KeySaveResult {
110	    KeySaveStatus status = KeySaveStatus::kNotCreated;
111	    std::string error;           // why the save did not succeed; empty on success
112	    std::string removalWarning;  // populated only for kCleanupFailed
113	
114	    bool saved() const { return status == KeySaveStatus::kSaved; }
115	};
116	
117	// Owns the descriptor opened for the newly created key file for the duration
118	// of one save attempt and closes it exactly once. Closing is centralized here
119	// rather than spread across the failure branches: a branch only records its
120	// reason, and the descriptor is still released on every path out of scope.
121	class FdGuard {
122	public:
123	    FdGuard() = default;
124	    explicit FdGuard(int fd) : fd_(fd) {}
125	    ~FdGuard() { close(); }
126	
127	    FdGuard(const FdGuard&) = delete;
128	    FdGuard& operator=(const FdGuard&) = delete;
129	    FdGuard(FdGuard&&) = delete;
130	    FdGuard& operator=(FdGuard&&) = delete;
131	
132	    int get() const { return fd_; }
133	
134	    // Closes and disarms the guard, reporting close(2)'s status. Used after
135	    // fsync(), where a reported failure means durability could not be
136	    // confirmed and success must not be reported. Must be called while armed.
137	    int finish() {
138	        const int fd = fd_;
139	        fd_ = -1;
140	        return ::close(fd);
141	    }
142	
143	    // Best-effort close for failure paths: the save has already failed, and
144	    // close(2) releases the descriptor even when it reports an error, so the
145	    // result is intentionally discarded here. Idempotent via disarming.
146	    void close() {
147	        if (fd_ != -1) {
148	            const int fd = fd_;
149	            fd_ = -1;
150	            ::close(fd);
151	        }
152	    }
153	
154	private:
155	    int fd_ = -1;
156	};
157	
158	// Forces the freshly created key file to exactly 0600: owner read/write, no
159	// execute bit, no group/other access. The mode given to open() is still
160	// reduced by the inherited process umask, which can strip owner read (umask
161	// 0400), owner write (umask 0200), or both (umask 0600); fchmod() is not
162	// affected by the umask. The result is verified with fstat() so a filesystem
163	// that silently keeps different permissions is treated as a failure instead
164	// of being reported as a success.
165	bool fixKeyFilePermissions(int fd, const std::string& path,
166	                           std::string& error) {
167	    if (::fchmod(fd, S_IRUSR | S_IWUSR) != 0) {
168	        error = "cannot set key file permissions to 0600 on '" + path +
169	                "': " + errnoDescription(errno);
170	        return false;
171	    }
172	    struct stat info;
173	    if (::fstat(fd, &info) != 0) {
174	        error = "cannot verify key file permissions on '" + path +
175	                "': " + errnoDescription(errno);
176	        return false;
177	    }
178	    if ((info.st_mode & 0777) != (S_IRUSR | S_IWUSR)) {
179	        error = "cannot guarantee key file permissions 0600 on '" + path +
180	                "'";
181	        return false;
182	    }
183	    return true;
